#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i = 0; i < 10; i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    for(int i = 0; i < m; i++){
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
    }

    // Sort adjacency lists for binary search edge checking
    for(int i = 1; i <= n; i++){
        sort(adj[i].begin(), adj[i].end());
        sort(radj[i].begin(), radj[i].end());
    }

    auto he = [&](int u, int v) -> bool {
        return binary_search(adj[u].begin(), adj[u].end(), v);
    };

    auto now = chrono::steady_clock::now;
    auto start_time = now();
    auto elapsed_ms = [&](){return chrono::duration_cast<chrono::milliseconds>(now()-start_time).count();};

    // DAG check
    {
        vector<int> indeg(n+1, 0);
        for(int u = 1; u <= n; u++) for(int v : adj[u]) indeg[v]++;
        queue<int> q;
        for(int u = 1; u <= n; u++) if(indeg[u] == 0) q.push(u);
        vector<int> topo; topo.reserve(n);
        while(!q.empty()){
            int u = q.front(); q.pop(); topo.push_back(u);
            for(int v : adj[u]) if(--indeg[v] == 0) q.push(v);
        }
        if((int)topo.size() == n){
            vector<int> dp(n+1, 1), nxt(n+1, -1);
            for(int i = n-1; i >= 0; i--){
                int u = topo[i]; dp[u] = 1; nxt[u] = -1;
                for(int v : adj[u]){
                    if(dp[v] + 1 > dp[u]){ dp[u] = dp[v] + 1; nxt[u] = v; }
                }
            }
            int bs = topo[0];
            for(int u : topo) if(dp[u] > dp[bs]) bs = u;
            vector<int> path;
            for(int u = bs; u != -1; u = nxt[u]) path.push_back(u);
            cout << path.size() << "\n";
            for(int i = 0; i < (int)path.size(); i++){ if(i) cout << ' '; cout << path[i]; }
            cout << "\n";
            return 0;
        }
    }

    mt19937 rng(42);
    vector<int> best_path;

    while(elapsed_ms() < 3800 && (int)best_path.size() < n){
        int sv = rng() % n + 1;
        deque<int> path;
        vector<bool> used(n+1, false);
        vector<int> pos(n+1, -1);
        path.push_back(sv); used[sv] = true;

        auto try_extend = [&]() -> bool {
            bool progress = false;
            // extend back
            while(true){
                int c = path.back(), best=-1, bs=INT_MAX;
                for(int v : adj[c]) if(!used[v]){
                    int s = adj[v].size();
                    if(s < bs || (s == bs && (rng()%3==0))){ bs=s; best=v; }
                }
                if(best==-1) break;
                used[best]=true; path.push_back(best); progress=true;
            }
            // extend front
            while(true){
                int c = path.front(), best=-1, bs=INT_MAX;
                for(int v : radj[c]) if(!used[v]){
                    int s = radj[v].size();
                    if(s < bs || (s == bs && (rng()%3==0))){ bs=s; best=v; }
                }
                if(best==-1) break;
                used[best]=true; path.push_front(best); progress=true;
            }
            return progress;
        };

        auto try_rotate = [&]() -> bool {
            int L = path.size();
            // Try rotating from back
            int last = path.back();
            vector<int> cands;
            for(int v : adj[last]){
                // find position of v in path
                // rebuild pos
                for(int i=0;i<L;i++) pos[path[i]]=i;
                if(pos[v] >= 0 && pos[v] < L-1){
                    cands.push_back(pos[v]);
                }
            }
            // rebuild pos
            for(int i=0;i<L;i++) pos[path[i]]=i;
            if(!cands.empty()){
                int idx = cands[rng()%cands.size()];
                // reverse path[idx+1..L-1], then last->path[idx]->...
                // new path: path[0..idx], path[L-1], path[L-2], ..., path[idx+1]
                // Check: he(last, path[idx])? No, we need he(path[idx], path[idx+1]) replaced.
                // Actually: path[idx]->path[idx+1] exists (original). We want path[last]->path[idx+1..L-1] reversed.
                // path becomes: path[0..idx], last, path[L-2], path[L-3], ..., path[idx+1]
                // need: he(path[idx], last)? No, he(last, path[idx]) is what we have from adj[last].
                // Hmm, we need path[idx]->last edge? No. We have last->path[idx] but we need directed.
                // Actually adj[last] contains v=path[idx], meaning last->path[idx] edge exists.
                // So new end after reverse: path[idx+1] (the old idx+1 becomes new end)
                // Edges needed: he(last, path[idx])=yes (from cands). Then reversed segment: he(path[i+1],path[i]) for i in [idx+1,L-2]
                // This is expensive to verify. Let's just try:
                // Reverse suffix from idx+1 to end
                vector<int> vp(path.begin(), path.end());
                reverse(vp.begin()+idx+1, vp.end());
                // insert last->path[idx] link: vp[idx] then vp[idx+1]=last
                // Check all edges in reversed part
                bool ok = true;
                if(ok && !he(vp[idx], vp[idx+1])) ok=false;
                for(int i=idx+1;i<L-1 && ok;i++) if(!he(vp[i],vp[i+1])) ok=false;
                if(ok){
                    path.clear();
                    for(int x:vp) path.push_back(x);
                    return true;
                }
            }
            return false;
        };

        try_extend();
        for(int t = 0; t < 200 && elapsed_ms() < 3800; t++){
            if(try_rotate()) try_extend();
        }

        if((int)path.size() > (int)best_path.size()){
            best_path.assign(path.begin(), path.end());
        }
    }

    cout << best_path.size() << "\n";
    for(int i=0;i<(int)best_path.size();i++){ if(i) cout<<' '; cout<<best_path[i]; }
    cout << "\n";
    return 0;
}
